  Definition drain_W (spv C LG : Z) (ng : Z) : list ivl :=
    [(spv + -48, spv); (AINST + OI_QMUTEX, AINST + OI_QMUTEX + 8); (AINST + OI_GQ, AINST + OI_GQ + 32); (C, C + 32)]
